PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "kysely_migration" ("name" varchar(255) not null primary key, "timestamp" varchar(255) not null);
CREATE TABLE IF NOT EXISTS "kysely_migration_lock" ("id" varchar(255) not null primary key, "is_locked" integer default 0 not null);
CREATE TABLE IF NOT EXISTS "StudioCMSUsersTable" ("id" text primary key, "url" text, "name" text not null, "email" text, "avatar" text, "username" text not null, "password" text, "updatedAt" text not null, "createdAt" text default CURRENT_TIMESTAMP not null, "emailVerified" integer default 0 not null, "notifications" text);
CREATE TABLE IF NOT EXISTS "StudioCMSOAuthAccounts" ("providerUserId" text not null, "provider" text not null, "userId" text not null references "StudioCMSUsersTable" ("id"));
CREATE TABLE IF NOT EXISTS "StudioCMSSessionTable" ("id" text primary key, "userId" text not null references "StudioCMSUsersTable" ("id"), "expiresAt" text not null);
CREATE TABLE IF NOT EXISTS "StudioCMSPermissions" ("user" text not null references "StudioCMSUsersTable" ("id"), "rank" text not null);
CREATE TABLE IF NOT EXISTS "StudioCMSAPIKeys" ("id" text primary key, "userId" text not null references "StudioCMSUsersTable" ("id"), "key" text not null, "creationDate" text not null, "description" text);
CREATE TABLE IF NOT EXISTS "StudioCMSUserResetTokens" ("id" text primary key, "userId" text not null references "StudioCMSUsersTable" ("id"), "token" text not null);
CREATE TABLE IF NOT EXISTS "StudioCMSPageFolderStructure" ("id" text primary key, "name" text not null, "parent" text);
CREATE TABLE IF NOT EXISTS "StudioCMSPageData" ("id" text primary key, "package" text not null, "title" text not null, "description" text not null, "showOnNav" integer default 0 not null, "publishedAt" text, "updatedAt" text not null, "slug" text not null, "contentLang" text not null, "heroImage" text, "categories" text default '[]' not null, "tags" text default '[]' not null, "authorId" text not null, "contributorIds" text default '[]' not null, "showAuthor" integer default 0 not null, "showContributors" integer default 0 not null, "parentFolder" text, "draft" integer default 0 not null, "augments" text default '[]' not null);
CREATE TABLE IF NOT EXISTS "StudioCMSDiffTracking" ("id" text primary key, "pageId" text not null references "StudioCMSPageData" ("id"), "userId" text not null references "StudioCMSUsersTable" ("id"), "timestamp" text not null, "pageMetaData" text not null, "pageContentStart" text not null, "diff" text);
CREATE TABLE IF NOT EXISTS "StudioCMSPageDataTags" ("id" integer primary key, "description" text not null, "name" text not null, "slug" text not null, "meta" text not null);
CREATE TABLE IF NOT EXISTS "StudioCMSPageDataCategories" ("id" integer primary key, "parent" integer, "description" text not null, "name" text not null, "slug" text not null, "meta" text not null);
CREATE TABLE IF NOT EXISTS "StudioCMSPageContent" ("id" text primary key, "contentId" text not null references "StudioCMSPageData" ("id"), "contentLang" text not null, "content" text not null);
CREATE TABLE IF NOT EXISTS "StudioCMSEmailVerificationTokens" ("id" text primary key, "userId" text not null references "StudioCMSUsersTable" ("id"), "token" text not null, "expiresAt" text not null);
CREATE TABLE IF NOT EXISTS "StudioCMSPluginData" ("id" text primary key, "data" text not null);
CREATE TABLE IF NOT EXISTS "StudioCMSDynamicConfigSettings" ("id" text primary key, "data" text not null);
CREATE TABLE IF NOT EXISTS "_kysely_schema_v1" ("id" integer primary key, "definition" text not null);
CREATE TABLE IF NOT EXISTS "StudioCMSStorageManagerUrlMappings" ("identifier" text primary key, "url" text not null, "isPermanent" integer default 0 not null, "expiresAt" integer, "createdAt" integer not null, "updatedAt" integer not null);
COMMIT;
