INSERT INTO StudioCMSPageContent VALUES('page-hero-content-en','page-hero','en','{"subtitle":"One People. One Planet. One Nature.","title":"Embrace Nature","backgroundImage":"/images/hero/banner.webp","showStars":true}');
INSERT INTO StudioCMSPageContent VALUES('page-about-content-en','page-about','en','{"subtitle":"One Nature Hotels","title":"Embrace Nature, Experience Luxury","description":"Two Nature Hotels is a collection of ultra-luxury boutique hotels and camps that balance premium luxury with unwavering ecological responsibility. Our properties offer an exclusive and intimate safari experience in the heart of the Serengeti.","imageUrl":"/images/about/leopard.webp","ctaText":"Know More","ctaLink":"/about-us/"}');
INSERT INTO StudioCMSPageContent VALUES('page-property-mara-river-content-en','page-property-mara-river','en','{"location":"Serengeti National Park, Tanzania","title":"One Nature Mara River","description":"Seven luxurious villas situated in the heart of the Great Migration River Crossing, offering an unparalleled safari experience with breathtaking views of the Mara River.","imageUrls":["/images/mara-river/bedroom1.webp","/images/mara-river/pool.webp","/images/mara-river/bedroom2.webp"],"ctaText":"Know More","ctaLink":"/mara-river/","reversed":false}');
INSERT INTO StudioCMSPageContent VALUES('page-property-nyaruswiga-content-en','page-property-nyaruswiga','en','{"location":"Serengeti National Park, Tanzania","title":"One Nature Nyaruswiga","description":"Fourteen ultra-luxurious tents nestled in the Central Serengeti, offering an exclusive and intimate safari experience with world-class amenities and stunning views.","imageUrls":["/images/nyaruswiga/tent1.webp","/images/nyaruswiga/family-lounge.webp","/images/nyaruswiga/tent2.webp"],"ctaText":"Know More","ctaLink":"/nyaruswiga/","reversed":true}');
INSERT INTO StudioCMSPageContent VALUES('page-wilderness-content-en','page-wilderness','en','{"title":"Where Comfort and Luxury Meet Wilderness","description":"Our exclusive and secluded destinations offer the perfect blend of premium comfort and raw natural beauty. Each property is carefully designed to immerse you in the African wilderness while providing world-class amenities and service.","imageUrl":"/images/experiences/safari-drive.webp"}');
INSERT INTO StudioCMSPageContent VALUES('page-experiences-content-en','page-experiences','en','{"subtitle":"Experiences","title":"Enriching Experiences Await with Every Stay","description":"From cultural delights to gastronomic experiences and thrilling adventures, every moment at Two Nature Hotels is designed to create lasting memories. Discover the magic of the Serengeti through our curated experiences.","imageUrls":["/images/hero/banner.webp","/images/experiences/balloon-safari.webp"],"features":["Hot Air Balloon Safaris","Guided Game Drives","Cultural Village Visits","Bush Dining Experiences"]}');
INSERT INTO StudioCMSPageContent VALUES('page-sustainability-content-en','page-sustainability','en','{"subtitle":"Sustainability","title":"Preservation and Luxury Unite","description":"Our eco-friendly accommodations and conservation initiatives ensure that the beauty of Africa is preserved for generations to come. We believe in responsible tourism that benefits both the environment and local communities.","motto":"One People. One Planet. One Nature.","quote":"Beyond a stay, it is a captivating journey — a shared heartbeat with the Earth.","bgImage":"/images/hero/banner.webp"}');
INSERT INTO StudioCMSPageContent VALUES('page-trip-planning-content-en','page-trip-planning','en','{"title":"Let us plan your trip","subtitle":"Discover Your Perfect Escape and Customize Your Journey","features":["Expert Guidance","Personalized Itineraries","Tailored Services"],"ctaText":"Contact Us","ctaLink":"/contact-us/","imageUrl":"/images/experiences/lioness-cub.webp"}');
INSERT INTO StudioCMSPageContent VALUES('page-footer-content-en','page-footer','en','{"logoUrl":"/images/logos/white.svg","newsletterText":"Subscribe to Our Newsletter","newsletterSubtext":"Stay updated with our latest news and offers","phone":["+971 4 558 6911","+255 688 767676"],"address":"Arusha, Tanzania","email":"info@onenaturehotels.com","socialLinks":[{"name":"Facebook","href":"https://www.facebook.com/onenatureresorts/","icon":"facebook"},{"name":"Instagram","href":"https://www.instagram.com/onenaturehotels/","icon":"instagram"},{"name":"YouTube","href":"https://www.youtube.com/@onenaturehotels","icon":"youtube"},{"name":"TikTok","href":"https://www.tiktok.com/@onenaturehotels","icon":"tiktok"},{"name":"LinkedIn","href":"https://www.linkedin.com/company/onenaturehotels","icon":"linkedin"},{"name":"TripAdvisor","href":"https://www.tripadvisor.com/Hotel_Review-g317730-d26398462-Reviews-One_Nature_Nyaruswiga-Serengeti_National_Park.html","icon":"tripadvisor"}],"navItems":[{"label":"Home","href":"/"},{"label":"About Us","href":"/about-us/"},{"label":"Media","href":"/media/"},{"label":"Blog","href":"/blog/"},{"label":"Contact Us","href":"/contact-us/"}],"legalLinks":[{"label":"Privacy Policy","href":"/privacy-policy/"},{"label":"General Terms","href":"/general-terms/"},{"label":"Trading Terms","href":"/trading-terms/"}]}');
INSERT INTO StudioCMSPageContent VALUES('page-blog-carousel-content-en','page-blog-carousel','en','{"subtitle":"News, Articles, & More","title":"Blog","posts":[{"title":"Nature''s Masterpieces: The Hidden Purpose Behind Animal Patterns in the Serengeti","category":"Animals","date":"Sep 08","image":"/images/blog/animal-patterns.webp","href":"/blog/natures-masterpieces/"},{"title":"Why Serengeti Holidays with Families and Friends Are Best for the Festive Season","category":"Highlights","date":"Nov 20","image":"/images/blog/festive.webp","href":"/blog/serengeti-holidays-families/"},{"title":"Wildlife Conservation: How Two Nature Stands Tall for Wildlife and Communities","category":"Conservation","date":"Dec 03","image":"/images/blog/conservation.webp","href":"/blog/wildlife-conservation/"},{"title":"Giraffes of the Serengeti: What Makes Them So Special","category":"Animals","date":"Jan 15","image":"/images/blog/giraffes.webp","href":"/blog/giraffes-of-the-serengeti/"},{"title":"Dung Architects: The Unsung Engineers of the Serengeti","category":"Animals","date":"Jan 10","image":"/images/blog/dung-beetles.webp","href":"/blog/dung-architects/"},{"title":"Valentine''s Day Getaway 2026","category":"Highlights","date":"Dec 10","image":"/images/blog/valentines.webp","href":"/blog/valentines-day-getaway/"},{"title":"10 Best Animals to See in the Serengeti","category":"Animals","date":"Dec 05","image":"/images/blog/best-animals.webp","href":"/blog/10-best-animals/"},{"title":"Spring Break in the Serengeti","category":"Highlights","date":"Nov 28","image":"/images/blog/spring-break.webp","href":"/blog/spring-break-serengeti/"}]}');
